Listing 21-25: Shutting down the server after serving two requests by exiting the loop
You wouldn’t want a real-world web server to shut down after serving only two requests. This
code just demonstrates that the graceful shutdown and cleanup is in working order.
impl Worker {
fn new(id: usize, receiver: Arc<Mutex<mpsc::Receiver<Job>>>) -> Worker {
let thread = thread::spawn(move || {
loop {
let message = receiver.lock().unwrap().recv();
match message {
Ok(job) => {
println!("Worker {id} got a job; executing.");
job();
}
Err(_) => {
println!("Worker {id} disconnected; shutting down.");
break;
}
}
}
});
Worker { id, thread }
}
}
